package dev.gravaai.ui.kit;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * The icon resources are generated by {@code java/tools/extract-icons.mjs}; these tests make sure
 * every name the kit exposes and every extracted file is present on the classpath (plan §5.12:
 * never hand-draw icons, so a missing glyph is a broken build).
 */
class IconsTest {

	@DisplayName("every Icons constant resolves to an extracted SVG")
	@Test
	void constantsResolve() throws IllegalAccessException {
		int count = 0;
		for (Field field : Icons.class.getDeclaredFields()) {
			if (!Modifier.isStatic(field.getModifiers()) || field.getType() != String.class) {
				continue;
			}
			String name = (String) field.get(null);
			assertNotNull(Icon.class.getResource(Icon.resolveResource(name, "")),
					"icon resource for Icons." + field.getName() + " (" + name + ")");
			count++;
		}
		assertTrue(count >= 95, "expected the icons.tsx exports (got " + count + ")");
	}

	@DisplayName("solar icons have both linear and bold variants, phosphor all six weights")
	@Test
	void weightVariants() {
		for (String name : new String[] {Icons.MicrophoneIcon, Icons.PlayIcon, Icons.Trash,
				Icons.Check, Icons.CaretDown}) {
			assertNotNull(Icon.class.getResource(Icon.resolveResource(name, "linear")), name + " linear");
			assertNotNull(Icon.class.getResource(Icon.resolveResource(name, "bold")), name + " bold");
		}
		for (String name : new String[] {"phosphor/Export", "phosphor/GoogleLogo", "phosphor/XLogo"}) {
			for (String weight : new String[] {"regular", "thin", "light", "bold", "fill", "duotone"}) {
				assertNotNull(Icon.class.getResource(Icon.resolveResource(name, weight)),
						name + " " + weight);
			}
		}
	}

	@DisplayName("the extraction manifest lists 182 files and every one is on the classpath")
	@Test
	void manifestComplete() throws Exception {
		List<String> missing = new ArrayList<>();
		int count = 0;
		try (InputStream in = IconsTest.class.getResourceAsStream("/kit/icons/manifest.txt")) {
			assertNotNull(in, "manifest.txt");
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			for (String line = reader.readLine(); line != null; line = reader.readLine()) {
				if (line.isBlank()) {
					continue;
				}
				count++;
				String resource = "/kit/icons/" + line + ".svg";
				if (IconsTest.class.getResource(resource) == null) {
					missing.add(resource);
				}
			}
		}
		assertTrue(missing.isEmpty(), "missing icon resources: " + missing);
		assertTrue(count >= 182, "expected at least 182 extracted icons, got " + count);
	}

	@DisplayName("the composite MicrophoneSlash glyph exists in both weights")
	@Test
	void composites() {
		assertNotNull(Icon.class.getResource("/kit/icons/solar/linear/MicrophoneSlash.svg"));
		assertNotNull(Icon.class.getResource("/kit/icons/solar/bold/MicrophoneSlash.svg"));
	}
}
